@Slf4j
@PluginDescriptor(
	name = "Clean Chat",
	description = "Hide clan name and more to clean your chat channels, includes GIM, friends, and clan chats",
	tags = {"clean", "chat", "clan", "friends", "gim", "group", "iron", "ironman", "channel", "color", "hide", "remove", "custom", "timestamp"}
)
public class CleanChatChannelsPlugin extends Plugin
{

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private CleanChatChannelsConfig config;

	@Inject
	private ChannelNameManager channelNameManager;

	@Inject
	private ChatWidgetEditor chatWidgetEditor;

	@Inject
	private ChatBlocker chatBlocker;

	@Inject
	private EventBus eventBus;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ChatColorBarOverlay colorBarOverlay;

	@Inject
	private ChatTimestampOverlay timestampOverlay;

	@Inject
	private TimestampPluginIntegration timestampIntegration;

	@Provides
	CleanChatChannelsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CleanChatChannelsConfig.class);
	}

	@Provides
	TimestampConfig provideTimestampConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TimestampConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		timestampIntegration.onStartup();

		eventBus.register(chatBlocker);
		eventBus.register(chatWidgetEditor);
		eventBus.register(channelNameManager);
		eventBus.register(timestampIntegration);
		channelNameManager.startup();
		eventBus.register(timestampOverlay);
		overlayManager.add(timestampOverlay);
		timestampOverlay.startUp();
		overlayManager.add(colorBarOverlay);

		clientThread.invoke(() -> handleScrollbarVisibility());

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			log.debug("Plugin enabled. Refreshing chat.");
			client.refreshChat();
		}

		ChangeLogUtil.handleChangelog(config, chatMessageManager, client);
	}

	@Override
	protected void shutDown() throws Exception
	{
		eventBus.unregister(chatBlocker);
		eventBus.unregister(chatWidgetEditor);
		eventBus.unregister(channelNameManager);
		eventBus.unregister(timestampIntegration);
		channelNameManager.shutdown();
		overlayManager.remove(timestampOverlay);
		eventBus.unregister(timestampOverlay);
		overlayManager.remove(colorBarOverlay);

		// Remove all our shenanigans
		log.debug("Plugin disabled. Refreshing chat.");
		clientThread.invoke(() -> handleScrollbarVisibility(false));
		client.refreshChat();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (Objects.equals(event.getGroup(), CleanChatChannelsConfig.GROUP))
		{
			log.debug("Config changed. Refreshing chat.");
			client.refreshChat();

			if (Objects.equals(event.getKey(), HIDE_SCROLLBAR_KEY))
			{
				clientThread.invoke(() -> handleScrollbarVisibility());
			}
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.CHATBOX)
		{
			handleScrollbarVisibility();
		}
	}

	private void handleScrollbarVisibility()
	{
		handleScrollbarVisibility(config.hideScrollbar());
	}

	private void handleScrollbarVisibility(boolean hideScrollbar)
	{
		Widget chatbox = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
		Widget scrollBarContainer = client.getWidget(InterfaceID.Chatbox.CHATSCROLLBAR);
		if (chatbox != null && scrollBarContainer != null) {
			scrollBarContainer.setHidden(hideScrollbar);

			// width mode is MINUS, so we if we want to match the parent width we use 0
			if (hideScrollbar) {
				chatbox.setOriginalWidth(0);
			} else {
				chatbox.setOriginalWidth(scrollBarContainer.getWidth());
			}
			chatbox.revalidate();

			client.refreshChat();
		}
	}

}

package com.github.ldavid432.cleanchat;

import com.github.ldavid432.cleanchat.util.FormatterExtractor;
import java.awt.Color;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.timestamp.TimestampConfig;

@Slf4j
@Singleton
public class TimestampPluginIntegration
{
	private static final String RUNELITE_CONFIG_GROUP = "runelite";
	private static final String TIMESTAMP_PLUGIN_KEY = "timestampplugin";

	public static final String TIMESTAMP_FORMAT_KEY = "format";
	private static final String OPAQUE_TIMESTAMP_COLOR_KEY = "opaqueTimestamp";
	private static final String TRANSPARENT_TIMESTAMP_COLOR_KEY = "transparentTimestamp";

	@Inject
	private ConfigManager configManager;

	@Inject
	private Client client;

	@Inject
	private CleanChatChannelsConfig config;

	@Inject
	private TimestampConfig timestampConfig;

	private boolean isTimestampPluginEnabled;

	@Getter
	@Nullable
	private Color opaqueTimestampColor;

	@Getter
	@Nullable
	private Color transparentTimestampColor;

	@Getter
	private String timestampFormat;

	@Getter
	@Setter
	private int timestampTemplateWidth = 0;

	@Getter
	@Setter
	@Nullable
	private FormatterExtractor.ExtractionResult timestampTemplate = null;

	public void onStartup()
	{
		isTimestampPluginEnabled = configManager.getConfiguration(RUNELITE_CONFIG_GROUP, TIMESTAMP_PLUGIN_KEY, Boolean.class) == Boolean.TRUE;
		opaqueTimestampColor = timestampConfig.opaqueTimestamp();
		transparentTimestampColor = timestampConfig.transparentTimestamp();
		timestampFormat = timestampConfig.timestampFormat();
	}

	public boolean isFixedWidthTimestampEnabled()
	{
		return isTimestampPluginEnabled && config.isFixedWidthTimestampEnabled();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (TimestampConfig.GROUP.equals(event.getGroup()))
		{
			switch (event.getKey())
			{
				case TIMESTAMP_FORMAT_KEY:
					timestampFormat = timestampConfig.timestampFormat();
					log.debug("Timestamp format changed. Refreshing chat.");
					client.refreshChat();
					break;
				case OPAQUE_TIMESTAMP_COLOR_KEY:
					opaqueTimestampColor = timestampConfig.opaqueTimestamp();
					break;
				case TRANSPARENT_TIMESTAMP_COLOR_KEY:
					transparentTimestampColor = timestampConfig.transparentTimestamp();
					break;
			}
		}
		else if (RUNELITE_CONFIG_GROUP.equals(event.getGroup()) && TIMESTAMP_PLUGIN_KEY.equals(event.getKey()))
		{
			isTimestampPluginEnabled = Boolean.parseBoolean(event.getNewValue());
			log.debug("Timestamp plugin toggled. Refreshing chat.");
			client.refreshChat();
		}
	}
}

